INSERT INTO questions(id,data) VALUES
('10a1-w10-p165-q1',$question_json${"id":"10a1-w10-p165-q1","classroom":"10A1","examWeek":10,"position":18,"type":"MCQ","exam":"10A1 · 10th week practice","topic":"Page 165 · Q1 · Geometric mean · الوسط الهندسي","marks":1,"prompt":"Find the geometric mean between $4$ and $6$. Give the positive exact value in simplest radical form. Choose the correct answer.","promptAr":"أوجد الوسط الهندسي بين $4$ و$6$. اكتب القيمة الموجبة الدقيقة بأبسط صورة جذرية. اختر الإجابة الصحيحة.","answer":"The geometric mean is $g=\\sqrt{ab}=\\sqrt{24}=2\\sqrt6$. Use the positive root.","answerAr":"الوسط الهندسي $g=\\sqrt{ab}=\\sqrt{24}=2\\sqrt6$. نأخذ الجذر الموجب.","diagram":"none","difficulty":"Standard","image":"","options":["$24$","$2\\sqrt6$","$10$","$\\sqrt{10}$"],"optionsAr":["$24$","$2\\sqrt6$","$10$","$\\sqrt{10}$"],"sourcePage":165,"sourceQuestion":1,"expectedValues":{"mean":4.898979485566356},"geometricMean":[4,6],"correctIndex":1}$question_json$::jsonb),
('10a1-w10-p165-q2',$question_json${"id":"10a1-w10-p165-q2","classroom":"10A1","examWeek":10,"position":19,"type":"MCQ","exam":"10A1 · 10th week practice","topic":"Page 165 · Q2 · Geometric mean · الوسط الهندسي","marks":1,"prompt":"Find the geometric mean between $\\frac12$ and $2$. Give the positive exact value in simplest radical form. Choose the correct answer.","promptAr":"أوجد الوسط الهندسي بين $\\frac12$ و$2$. اكتب القيمة الموجبة الدقيقة بأبسط صورة جذرية. اختر الإجابة الصحيحة.","answer":"The geometric mean is $g=\\sqrt{ab}=\\sqrt{1}=1$. Use the positive root.","answerAr":"الوسط الهندسي $g=\\sqrt{ab}=\\sqrt{1}=1$. نأخذ الجذر الموجب.","diagram":"none","difficulty":"Standard","image":"","options":["$2.5$","$\\sqrt2$","$1$","$1.25$"],"optionsAr":["$2.5$","$\\sqrt2$","$1$","$1.25$"],"sourcePage":165,"sourceQuestion":2,"expectedValues":{"mean":1},"geometricMean":[0.5,2],"correctIndex":2}$question_json$::jsonb),
('10a1-w10-p165-q3',$question_json${"id":"10a1-w10-p165-q3","classroom":"10A1","examWeek":10,"position":20,"type":"MCQ","exam":"10A1 · 10th week practice","topic":"Page 165 · Q3 · Geometric mean · الوسط الهندسي","marks":1,"prompt":"Find the geometric mean between $4$ and $25$. Give the positive exact value in simplest radical form. Choose the correct answer.","promptAr":"أوجد الوسط الهندسي بين $4$ و$25$. اكتب القيمة الموجبة الدقيقة بأبسط صورة جذرية. اختر الإجابة الصحيحة.","answer":"The geometric mean is $g=\\sqrt{ab}=\\sqrt{100}=10$. Use the positive root.","answerAr":"الوسط الهندسي $g=\\sqrt{ab}=\\sqrt{100}=10$. نأخذ الجذر الموجب.","diagram":"none","difficulty":"Standard","image":"","options":["$29$","$100$","$14.5$","$10$"],"optionsAr":["$29$","$100$","$14.5$","$10$"],"sourcePage":165,"sourceQuestion":3,"expectedValues":{"mean":10},"geometricMean":[4,25],"correctIndex":3}$question_json$::jsonb),
('10a1-w10-p165-q4',$question_json${"id":"10a1-w10-p165-q4","classroom":"10A1","examWeek":10,"position":21,"type":"MCQ","exam":"10A1 · 10th week practice","topic":"Page 165 · Q4 · Geometric mean · الوسط الهندسي","marks":1,"prompt":"Find the geometric mean between $12$ and $20$. Give the positive exact value in simplest radical form. Choose the correct answer.","promptAr":"أوجد الوسط الهندسي بين $12$ و$20$. اكتب القيمة الموجبة الدقيقة بأبسط صورة جذرية. اختر الإجابة الصحيحة.","answer":"The geometric mean is $g=\\sqrt{ab}=\\sqrt{240}=4\\sqrt{15}$. Use the positive root.","answerAr":"الوسط الهندسي $g=\\sqrt{ab}=\\sqrt{240}=4\\sqrt{15}$. نأخذ الجذر الموجب.","diagram":"none","difficulty":"Standard","image":"","options":["$4\\sqrt{15}$","$16$","$2\\sqrt2$","$240$"],"optionsAr":["$4\\sqrt{15}$","$16$","$2\\sqrt2$","$240$"],"sourcePage":165,"sourceQuestion":4,"expectedValues":{"mean":15.491933384829668},"geometricMean":[12,20],"correctIndex":0}$question_json$::jsonb),
('10a1-w10-p165-q5',$question_json${"id":"10a1-w10-p165-q5","classroom":"10A1","examWeek":10,"position":22,"type":"MCQ","exam":"10A1 · 10th week practice","topic":"Page 165 · Q5 · Geometric mean · الوسط الهندسي","marks":1,"prompt":"Find the geometric mean between $17$ and $3$. Give the positive exact value in simplest radical form. Choose the correct answer.","promptAr":"أوجد الوسط الهندسي بين $17$ و$3$. اكتب القيمة الموجبة الدقيقة بأبسط صورة جذرية. اختر الإجابة الصحيحة.","answer":"The geometric mean is $g=\\sqrt{ab}=\\sqrt{51}=\\sqrt{51}$. Use the positive root.","answerAr":"الوسط الهندسي $g=\\sqrt{ab}=\\sqrt{51}=\\sqrt{51}$. نأخذ الجذر الموجب.","diagram":"none","difficulty":"Standard","image":"","options":["$51$","$\\sqrt{51}$","$10$","$20$"],"optionsAr":["$51$","$\\sqrt{51}$","$10$","$20$"],"sourcePage":165,"sourceQuestion":5,"expectedValues":{"mean":7.14142842854285},"geometricMean":[17,3],"correctIndex":1}$question_json$::jsonb),
('10a1-w10-p165-q6',$question_json${"id":"10a1-w10-p165-q6","classroom":"10A1","examWeek":10,"position":23,"type":"MCQ","exam":"10A1 · 10th week practice","topic":"Page 165 · Q6 · Geometric mean · الوسط الهندسي","marks":1,"prompt":"Find the geometric mean between $3$ and $24$. Give the positive exact value in simplest radical form. Choose the correct answer.","promptAr":"أوجد الوسط الهندسي بين $3$ و$24$. اكتب القيمة الموجبة الدقيقة بأبسط صورة جذرية. اختر الإجابة الصحيحة.","answer":"The geometric mean is $g=\\sqrt{ab}=\\sqrt{72}=6\\sqrt2$. Use the positive root.","answerAr":"الوسط الهندسي $g=\\sqrt{ab}=\\sqrt{72}=6\\sqrt2$. نأخذ الجذر الموجب.","diagram":"none","difficulty":"Standard","image":"","options":["$27$","$72$","$6\\sqrt2$","$13.5$"],"optionsAr":["$27$","$72$","$6\\sqrt2$","$13.5$"],"sourcePage":165,"sourceQuestion":6,"expectedValues":{"mean":8.48528137423857},"geometricMean":[3,24],"correctIndex":2}$question_json$::jsonb),
('10a1-w10-p165-q11',$question_json${"id":"10a1-w10-p165-q11","classroom":"10A1","examWeek":10,"position":24,"type":"MCQ","exam":"10A1 · 10th week practice","topic":"Page 165 · Q11 · Geometric mean · الوسط الهندسي","marks":1,"prompt":"In the right triangle, the marked altitude is perpendicular to the hypotenuse. Find x, y and z. Give exact simplified values; select the exact values. The hypotenuse is split into lengths 8 and 23. Choose the correct answer.","promptAr":"في المثلث القائم، الارتفاع المعلم عمودي على الوتر. أوجد x وy وz بالقيم الدقيقة المبسطة، ويمكنك إضافة قيم عشرية للتحقق إلى أقرب عُشر. قُسم الوتر إلى قطعتين طولهما 8 و23. اختر الإجابة الصحيحة.","answer":"The hypotenuse is $c=8+23=31$. Altitude: $x^2=8(23)$, so $x=2\\sqrt{46}\\approx13.6$. Legs: $y^2=31(8)$, so $y=2\\sqrt{62}\\approx15.7$; $z^2=31(23)$, so $z=\\sqrt{713}\\approx26.7$.","answerAr":"الوتر $c=8+23=31$. للارتفاع $x^2=8(23)$، ومنه $x=2\\sqrt{46}\\approx13.6$. وللضلعين $y^2=31(8)$، لذلك $y=2\\sqrt{62}\\approx15.7$؛ و$z^2=31(23)$، لذلك $z=\\sqrt{713}\\approx26.7$.","diagram":"week9-geometry","geometryDiagram":{"page":165,"number":11},"difficulty":"Standard","image":"","options":["$x=2\\sqrt{62},\\ y=2\\sqrt{46},\\ z=\\sqrt{713}$","$x=2\\sqrt{46},\\ y=\\sqrt{713},\\ z=2\\sqrt{62}$","$x=184,\\ y=248,\\ z=713$","$x=2\\sqrt{46},\\ y=2\\sqrt{62},\\ z=\\sqrt{713}$"],"optionsAr":["$x=2\\sqrt{62},\\ y=2\\sqrt{46},\\ z=\\sqrt{713}$","$x=2\\sqrt{46},\\ y=\\sqrt{713},\\ z=2\\sqrt{62}$","$x=184,\\ y=248,\\ z=713$","$x=2\\sqrt{46},\\ y=2\\sqrt{62},\\ z=\\sqrt{713}$"],"sourcePage":165,"sourceQuestion":11,"expectedValues":{"x":13.564659966250536,"y":15.748015748023622,"z":26.70205984563738},"correctIndex":3}$question_json$::jsonb),
('10a1-w10-p165-q12',$question_json${"id":"10a1-w10-p165-q12","classroom":"10A1","examWeek":10,"position":25,"type":"MCQ","exam":"10A1 · 10th week practice","topic":"Page 165 · Q12 · Geometric mean · الوسط الهندسي","marks":1,"prompt":"In the right triangle, the marked altitude is perpendicular to the hypotenuse. Find x, y and z. Give exact simplified values; select the exact values. The whole hypotenuse is 25 and its right-hand segment is 6. Choose the correct answer.","promptAr":"في المثلث القائم، الارتفاع المعلم عمودي على الوتر. أوجد x وy وz بالقيم الدقيقة المبسطة، ويمكنك إضافة قيم عشرية للتحقق إلى أقرب عُشر. طول الوتر كاملاً 25 وطول جزئه الأيمن 6. اختر الإجابة الصحيحة.","answer":"The other hypotenuse segment is $25-6=19$. $x^2=19(6)$ gives $x=\\sqrt{114}\\approx10.7$. $y^2=25(6)$ gives $y=5\\sqrt6\\approx12.2$. $z^2=25(19)$ gives $z=5\\sqrt{19}\\approx21.8$.","answerAr":"جزء الوتر الآخر $25-6=19$. من $x^2=19(6)$ نحصل على $x=\\sqrt{114}\\approx10.7$. ومن $y^2=25(6)$ نحصل على $y=5\\sqrt6\\approx12.2$. ومن $z^2=25(19)$ نحصل على $z=5\\sqrt{19}\\approx21.8$.","diagram":"week9-geometry","geometryDiagram":{"page":165,"number":12},"difficulty":"Standard","image":"","options":["$x=\\sqrt{114},\\ y=5\\sqrt6,\\ z=5\\sqrt{19}$","$x=\\sqrt{114},\\ y=5\\sqrt{19},\\ z=5\\sqrt6$","$x=6,\\ y=5\\sqrt6,\\ z=5\\sqrt{19}$","$x=114,\\ y=150,\\ z=475$"],"optionsAr":["$x=\\sqrt{114},\\ y=5\\sqrt6,\\ z=5\\sqrt{19}$","$x=\\sqrt{114},\\ y=5\\sqrt{19},\\ z=5\\sqrt6$","$x=6,\\ y=5\\sqrt6,\\ z=5\\sqrt{19}$","$x=114,\\ y=150,\\ z=475$"],"sourcePage":165,"sourceQuestion":12,"expectedValues":{"x":10.677078252031311,"y":12.24744871391589,"z":21.79449471770337},"correctIndex":0}$question_json$::jsonb),
('10a1-w10-p165-q13',$question_json${"id":"10a1-w10-p165-q13","classroom":"10A1","examWeek":10,"position":26,"type":"MCQ","exam":"10A1 · 10th week practice","topic":"Page 165 · Q13 · Geometric mean · الوسط الهندسي","marks":1,"prompt":"In the right triangle, the marked altitude is perpendicular to the hypotenuse. Find x, y and z. Give exact simplified values; select the exact values. The altitude is 3; the left hypotenuse segment is 2, the right segment is x, the whole hypotenuse is z, and the left leg is y. Choose the correct answer.","promptAr":"في المثلث القائم، الارتفاع المعلم عمودي على الوتر. أوجد x وy وz بالقيم الدقيقة المبسطة، ويمكنك إضافة قيم عشرية للتحقق إلى أقرب عُشر. طول الارتفاع 3، وجزء الوتر الأيسر 2 والأيمن x، وطول الوتر كاملاً z، والضلع الأيسر y. اختر الإجابة الصحيحة.","answer":"Altitude theorem: $3^2=2x$, so $x=\\frac92=4.5$. Thus $z=2+x=\\frac{13}{2}=6.5$. Leg theorem: $y^2=2z=13$, so $y=\\sqrt{13}\\approx3.6$.","answerAr":"من نظرية الارتفاع $3^2=2x$، لذلك $x=\\frac92=4.5$. ومنه $z=2+x=\\frac{13}{2}=6.5$. وبنظرية الضلع $y^2=2z=13$، لذلك $y=\\sqrt{13}\\approx3.6$.","diagram":"week9-geometry","geometryDiagram":{"page":165,"number":13},"difficulty":"Standard","image":"","options":["$x=3,\\ y=\\sqrt{10},\\ z=5$","$x=4.5,\\ y=\\sqrt{13},\\ z=6.5$","$x=6.5,\\ y=\\sqrt{13},\\ z=4.5$","$x=4.5,\\ y=13,\\ z=6.5$"],"optionsAr":["$x=3,\\ y=\\sqrt{10},\\ z=5$","$x=4.5,\\ y=\\sqrt{13},\\ z=6.5$","$x=6.5,\\ y=\\sqrt{13},\\ z=4.5$","$x=4.5,\\ y=13,\\ z=6.5$"],"sourcePage":165,"sourceQuestion":13,"expectedValues":{"x":4.5,"y":3.605551275463989,"z":6.5},"correctIndex":1}$question_json$::jsonb),
('10a1-w10-p165-q14',$question_json${"id":"10a1-w10-p165-q14","classroom":"10A1","examWeek":10,"position":27,"type":"MCQ","exam":"10A1 · 10th week practice","topic":"Page 165 · Q14 · Geometric mean · الوسط الهندسي","marks":1,"prompt":"In the right triangle, the marked altitude is perpendicular to the hypotenuse. Find x, y and z. Give exact simplified values; select the exact values. The whole hypotenuse is 20 and the right leg is 10. The hypotenuse parts are x and y; the left leg is z. Choose the correct answer.","promptAr":"في المثلث القائم، الارتفاع المعلم عمودي على الوتر. أوجد x وy وz بالقيم الدقيقة المبسطة، ويمكنك إضافة قيم عشرية للتحقق إلى أقرب عُشر. طول الوتر كاملاً 20 والضلع الأيمن 10. جزآ الوتر هما x وy، وطول الضلع الأيسر z. اختر الإجابة الصحيحة.","answer":"Leg theorem: $10^2=20y$, so $y=5$. Hence $x=20-5=15$. Then $z^2=20(15)=300$, so $z=10\\sqrt3\\approx17.3$.","answerAr":"من نظرية الضلع $10^2=20y$، ومنه $y=5$. إذن $x=20-5=15$. ثم $z^2=20(15)=300$، لذلك $z=10\\sqrt3\\approx17.3$.","diagram":"week9-geometry","geometryDiagram":{"page":165,"number":14},"difficulty":"Standard","image":"","options":["$x=15,\\ y=5,\\ z=5\\sqrt3$","$x=10,\\ y=10,\\ z=10$","$x=15,\\ y=5,\\ z=10\\sqrt3$","$x=5,\\ y=15,\\ z=10\\sqrt3$"],"optionsAr":["$x=15,\\ y=5,\\ z=5\\sqrt3$","$x=10,\\ y=10,\\ z=10$","$x=15,\\ y=5,\\ z=10\\sqrt3$","$x=5,\\ y=15,\\ z=10\\sqrt3$"],"sourcePage":165,"sourceQuestion":14,"expectedValues":{"x":15,"y":5,"z":17.320508075688775},"correctIndex":2}$question_json$::jsonb),
('10a1-w10-p171-q1',$question_json${"id":"10a1-w10-p171-q1","classroom":"10A1","examWeek":10,"exam":"10A1 · 10th week practice","topic":"Use the Pythagorean Theorem and its converse","type":"MCQ","marks":1,"difficulty":"Standard","diagram":"none","image":"","prompt":"Find the positive value of x in the marked right triangle. Use the Pythagorean Theorem.","promptAr":"أوجد القيمة الموجبة لـ x في المثلث القائم المعلم. استعمل نظرية فيثاغورس.","answer":"$x^2=3^2+3^2$. Thus $x=3\\sqrt2$.","answerAr":"نطبق نظرية فيثاغورس: مربع الوتر يساوي مجموع مربعي الضلعين القائمين، ثم نأخذ الجذر الموجب. $x=3\\sqrt2$.","options":["$9$","$\\sqrt6$","$3\\sqrt2$","$6$"],"optionsAr":["$9$","$\\sqrt6$","$3\\sqrt2$","$6$"],"sourcePage":171,"sourceQuestion":1,"rightTriangleDiagram":{"kind":"right","legs":[3,3],"labels":["3","3","x"]},"rightTriangleProblem":{"legs":[3,3],"hyp":4.242640687119286,"unknown":"hyp","choiceValues":[9,2.449489742783178,4.242640687119286,6]},"correctIndex":2}$question_json$::jsonb),
('10a1-w10-p171-q2',$question_json${"id":"10a1-w10-p171-q2","classroom":"10A1","examWeek":10,"exam":"10A1 · 10th week practice","topic":"Use the Pythagorean Theorem and its converse","type":"MCQ","marks":1,"difficulty":"Standard","diagram":"none","image":"","prompt":"Find the positive value of x in the marked right triangle. Use the Pythagorean Theorem.","promptAr":"أوجد القيمة الموجبة لـ x في المثلث القائم المعلم. استعمل نظرية فيثاغورس.","answer":"Subtract the known leg's square from the hypotenuse's square: $x^2=15^2-9^2$. Take the positive square root: $x=12$.","answerAr":"نطبق نظرية فيثاغورس: مربع الوتر يساوي مجموع مربعي الضلعين القائمين، ثم نأخذ الجذر الموجب. $x=12$.","options":["$6$","$18$","$24$","$12$"],"optionsAr":["$6$","$18$","$24$","$12$"],"sourcePage":171,"sourceQuestion":2,"rightTriangleDiagram":{"kind":"right","legs":[9,12],"labels":["9","x","15"]},"rightTriangleProblem":{"legs":[9,12],"hyp":15,"unknown":"legB","choiceValues":[6,18,24,12]},"correctIndex":3}$question_json$::jsonb),
('10a1-w10-p171-q3',$question_json${"id":"10a1-w10-p171-q3","classroom":"10A1","examWeek":10,"exam":"10A1 · 10th week practice","topic":"Use the Pythagorean Theorem and its converse","type":"MCQ","marks":1,"difficulty":"Standard","diagram":"none","image":"","prompt":"Find the positive value of x in the marked right triangle. Use the Pythagorean Theorem.","promptAr":"أوجد القيمة الموجبة لـ x في المثلث القائم المعلم. استعمل نظرية فيثاغورس.","answer":"Subtract the known leg's square from the hypotenuse's square: $x^2=65^2-25^2$. Take the positive square root: $x=60$.","answerAr":"نطبق نظرية فيثاغورس: مربع الوتر يساوي مجموع مربعي الضلعين القائمين، ثم نأخذ الجذر الموجب. $x=60$.","options":["$60$","$40$","$90$","$30$"],"optionsAr":["$60$","$40$","$90$","$30$"],"sourcePage":171,"sourceQuestion":3,"rightTriangleDiagram":{"kind":"right","legs":[25,60],"labels":["25","x","65"]},"rightTriangleProblem":{"legs":[25,60],"hyp":65,"unknown":"legB","choiceValues":[60,40,90,30]},"correctIndex":0}$question_json$::jsonb),
('10a1-w10-p171-q4',$question_json${"id":"10a1-w10-p171-q4","classroom":"10A1","examWeek":10,"exam":"10A1 · 10th week practice","topic":"Use the Pythagorean Theorem and its converse","type":"MCQ","marks":1,"difficulty":"Standard","diagram":"none","image":"","prompt":"Find the positive value of x in the marked right triangle. Use the Pythagorean Theorem.","promptAr":"أوجد القيمة الموجبة لـ x في المثلث القائم المعلم. استعمل نظرية فيثاغورس.","answer":"Subtract the known leg's square from the hypotenuse's square: $x^2=0.5555555555555556^2-0.4444444444444444^2$. Take the positive square root: $x=\\frac{1}{3}$.","answerAr":"نطبق نظرية فيثاغورس: مربع الوتر يساوي مجموع مربعي الضلعين القائمين، ثم نأخذ الجذر الموجب. $x=\\frac{1}{3}$.","options":["$1$","$\\frac{1}{3}$","$\\frac{1}{9}$","$\\frac{4}{9}$"],"optionsAr":["$1$","$\\frac{1}{3}$","$\\frac{1}{9}$","$\\frac{4}{9}$"],"sourcePage":171,"sourceQuestion":4,"rightTriangleDiagram":{"kind":"right","legs":[0.3333333333333333,0.4444444444444444],"labels":["x","4/9","5/9"]},"rightTriangleProblem":{"legs":[0.3333333333333333,0.4444444444444444],"hyp":0.5555555555555556,"unknown":"legA","choiceValues":[1,0.3333333333333333,0.1111111111111111,0.4444444444444444]},"correctIndex":1}$question_json$::jsonb),
('10a1-w10-p171-q5',$question_json${"id":"10a1-w10-p171-q5","classroom":"10A1","examWeek":10,"exam":"10A1 · 10th week practice","topic":"Use the Pythagorean Theorem and its converse","type":"MCQ","marks":1,"difficulty":"Standard","diagram":"none","image":"","prompt":"Find the positive value of x in the marked right triangle. Use the Pythagorean Theorem.","promptAr":"أوجد القيمة الموجبة لـ x في المثلث القائم المعلم. استعمل نظرية فيثاغورس.","answer":"$x^2=16^2+33^2$. Thus $x=\\sqrt{1345}$.","answerAr":"نطبق نظرية فيثاغورس: مربع الوتر يساوي مجموع مربعي الضلعين القائمين، ثم نأخذ الجذر الموجب. $x=\\sqrt{1345}$.","options":["$17$","$\\sqrt{833}$","$\\sqrt{1345}$","$49$"],"optionsAr":["$17$","$\\sqrt{833}$","$\\sqrt{1345}$","$49$"],"sourcePage":171,"sourceQuestion":5,"rightTriangleDiagram":{"kind":"right","legs":[16,33],"labels":["16","33","x"]},"rightTriangleProblem":{"legs":[16,33],"hyp":36.6742416417845,"unknown":"hyp","choiceValues":[17,28.861739379323623,36.6742416417845,49]},"correctIndex":2}$question_json$::jsonb),
('10a1-w10-p171-q6',$question_json${"id":"10a1-w10-p171-q6","classroom":"10A1","examWeek":10,"exam":"10A1 · 10th week practice","topic":"Use the Pythagorean Theorem and its converse","type":"MCQ","marks":1,"difficulty":"Standard","diagram":"none","image":"","prompt":"Find the positive value of x in the marked right triangle. The hypotenuse is 28 and the marked leg is 11. Use the Pythagorean Theorem.","promptAr":"أوجد القيمة الموجبة لـ x في المثلث القائم المعلم. طول الوتر 28 وطول الضلع المعلم 11. استعمل نظرية فيثاغورس.","answer":"Subtract the known leg's square from the hypotenuse's square: $x^2=28^2-11^2$. Take the positive square root: $x=\\sqrt{663}$.","answerAr":"نطبق نظرية فيثاغورس: مربع الوتر يساوي مجموع مربعي الضلعين القائمين، ثم نأخذ الجذر الموجب. $x=\\sqrt{663}$.","options":["$17$","$39$","$\\sqrt{905}$","$\\sqrt{663}$"],"optionsAr":["$17$","$39$","$\\sqrt{905}$","$\\sqrt{663}$"],"sourcePage":171,"sourceQuestion":6,"rightTriangleDiagram":{"kind":"right","legs":[11,25.748786379167466],"labels":["11","x","28"]},"rightTriangleProblem":{"legs":[11,25.748786379167466],"hyp":28,"unknown":"legB","choiceValues":[17,39,30.083217912982647,25.748786379167466]},"correctIndex":3}$question_json$::jsonb),
('10a1-w10-p171-q7',$question_json${"id":"10a1-w10-p171-q7","classroom":"10A1","examWeek":10,"exam":"10A1 · 10th week practice","topic":"Use the Pythagorean Theorem and its converse","type":"MCQ","marks":1,"difficulty":"Standard","diagram":"none","image":"","prompt":"Find the positive value of x in the marked right triangle. Use the Pythagorean Theorem.","promptAr":"أوجد القيمة الموجبة لـ x في المثلث القائم المعلم. استعمل نظرية فيثاغورس.","answer":"Subtract the known leg's square from the hypotenuse's square: $x^2=17^2-8^2$. Take the positive square root: $x=15$.","answerAr":"نطبق نظرية فيثاغورس: مربع الوتر يساوي مجموع مربعي الضلعين القائمين، ثم نأخذ الجذر الموجب. $x=15$.","options":["$15$","$9$","$25$","$12$"],"optionsAr":["$15$","$9$","$25$","$12$"],"sourcePage":171,"sourceQuestion":7,"rightTriangleDiagram":{"kind":"right","legs":[8,15],"labels":["8","x","17"]},"rightTriangleProblem":{"legs":[8,15],"hyp":17,"unknown":"legB","choiceValues":[15,9,25,12]},"correctIndex":0}$question_json$::jsonb),
('10a1-w10-p171-q8',$question_json${"id":"10a1-w10-p171-q8","classroom":"10A1","examWeek":10,"exam":"10A1 · 10th week practice","topic":"Use the Pythagorean Theorem and its converse","type":"MCQ","marks":1,"difficulty":"Standard","diagram":"none","image":"","prompt":"Find the positive value of x in the marked right triangle. Use the Pythagorean Theorem.","promptAr":"أوجد القيمة الموجبة لـ x في المثلث القائم المعلم. استعمل نظرية فيثاغورس.","answer":"$x^2=24^2+45^2$. Thus $x=51$.","answerAr":"نطبق نظرية فيثاغورس: مربع الوتر يساوي مجموع مربعي الضلعين القائمين، ثم نأخذ الجذر الموجب. $x=51$.","options":["$48$","$51$","$69$","$21$"],"optionsAr":["$48$","$51$","$69$","$21$"],"sourcePage":171,"sourceQuestion":8,"rightTriangleDiagram":{"kind":"right","legs":[24,45],"labels":["24","45","x"]},"rightTriangleProblem":{"legs":[24,45],"hyp":51,"unknown":"hyp","choiceValues":[48,51,69,21]},"correctIndex":1}$question_json$::jsonb),
('10a1-w10-p171-q9',$question_json${"id":"10a1-w10-p171-q9","classroom":"10A1","examWeek":10,"exam":"10A1 · 10th week practice","topic":"Use the Pythagorean Theorem and its converse","type":"MCQ","marks":1,"difficulty":"Standard","diagram":"none","image":"","prompt":"Find the positive value of x in the marked right triangle. Use the Pythagorean Theorem.","promptAr":"أوجد القيمة الموجبة لـ x في المثلث القائم المعلم. استعمل نظرية فيثاغورس.","answer":"$x^2=28^2+96^2$. Thus $x=100$.","answerAr":"نطبق نظرية فيثاغورس: مربع الوتر يساوي مجموع مربعي الضلعين القائمين، ثم نأخذ الجذر الموجب. $x=100$.","options":["$68$","$104$","$100$","$124$"],"optionsAr":["$68$","$104$","$100$","$124$"],"sourcePage":171,"sourceQuestion":9,"rightTriangleDiagram":{"kind":"right","legs":[28,96],"labels":["28","96","x"]},"rightTriangleProblem":{"legs":[28,96],"hyp":100,"unknown":"hyp","choiceValues":[68,104,100,124]},"correctIndex":2}$question_json$::jsonb),
